mapper.select:
SELECT id, document_id, user_id, active_version, status, content_hash, source,
       activated_at, purged_at, created_at, updated_at
FROM ai_document
WHERE document_id = #{documentId}
  AND user_id = #{userId}

mapper.update:
UPDATE ai_document
SET status = 'IMPORTING', updated_at = now()
WHERE document_id = #{documentId}
  AND user_id = #{userId}
  AND (status <> 'IMPORTING'
       OR updated_at < now() - make_interval(mins => #{staleMinutes}))

UPDATE ai_document
SET status = 'FAILED', updated_at = now()
WHERE document_id = #{documentId}
  AND user_id = #{userId}
  AND status = 'IMPORTING'

UPDATE ai_document
SET purged_at = now()
WHERE document_id = #{documentId}
  AND user_id = #{userId}
